import { VideoBackground } from "march/landing"
import { Button } from "march/ui"

// ruh hâli düğmesi: her basışta videonun üstündeki renk katmanı ve yazı değişir
const MOODS = [
  { tint: "dark", text: "Gece modu 🌙" },
  { tint: "light", text: "Sabah serinliği ☀️" },
  { tint: "brand", text: "Parti zamanı 🎉" },
] as const

export function MoodSwitch() {
  let $mood = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Button variant="secondary" on:click={() => $mood = ($mood + 1) % MOODS.length}>Ruh hâlini değiştir</Button>
    {() => {
      const m = MOODS[$mood]!
      return <VideoBackground src="/media/hadi-waves.webm" poster="/media/hadi-waves.jpg" tint={m.tint} tintOpacity={0.55}>
        <div sx={{ p: 6, text: "2xl" }}><strong>{m.text}</strong></div>
      </VideoBackground>
    }}
  </div>
}

import { VideoBackground } from "march/landing"
import { Button, toast } from "march/ui"
import { calendar } from "march/icons"

// bir butik otelin açılış bölümü: arkada sessiz deniz videosu, önde başlık ve rezervasyon düğmesi;
// veri tasarrufunda yalnız afiş görünür, köşedeki düğme videoyu durdurur
export function HotelHero() {
  return <VideoBackground src="/media/hadi-waves.webm" poster="/media/hadi-waves.jpg" tint="dark" tintOpacity={0.5} position="50% 40%"
    labels={{ play: "Videoyu oynat", pause: "Videoyu durdur" }}>
    <div sx={{ flex: "col", gap: 3, p: 8 }} style={{ color: "#fff" }}>
      <span sx={{ text: "sm" }}>BOZCAADA · 12 ODA</span>
      <strong sx={{ text: "2xl" }}>Denize sıfır, kalabalıktan uzak</strong>
      <span>Kahvaltı bağdan, akşam yemeği iskelede.</span>
      <Button icon={calendar} on:click={() => toast("Uygun tarihler gösteriliyor")}>Tarih seç</Button>
    </div>
  </VideoBackground>
}

import { test, expect, renderTest } from "march/testing"
import { VideoBackgroundLab } from "./VideoBackgroundLab.tsx"

// VideoBackgroundLab'in testleri: kaydedince Testler sekmesinde çalışır
test("kök sınıfı, koyu katman ve üstteki içerik", () => {
  const s = renderTest(() => <VideoBackgroundLab />)
  const root = s.get(".lab-vbg")
  expect(root?.classList.contains("m-vbg-tint-dark")).toBeTruthy()
  expect(s.get(".lab-vbg .m-vbg-tint")).not.toBe(null)
  expect(s.find("Dalgaların üstünde")).not.toBe(null)
})

test("afiş hemen görünür", () => {
  const s = renderTest(() => <VideoBackgroundLab />)
  expect(s.get(".lab-vbg img")?.getAttribute("src")).toContain("hadi-waves.jpg")
})

test("katman yok: renk katmanı kalkar", async () => {
  const s = renderTest(() => <VideoBackgroundLab />)
  await s.click("yok")
  expect(s.get(".lab-vbg")?.classList.contains("m-vbg-tint-none")).toBeTruthy()
  expect(s.get(".lab-vbg .m-vbg-tint")).toBe(null)
})

test("içerik videonun üstünde tıklanır; durdur düğmesi kapanınca gider", async () => {
  const s = renderTest(() => <VideoBackgroundLab />)
  await s.click("Beğen (0)")
  expect(s.find("Beğen (1)")).not.toBe(null)
  await s.click("Durdur düğmesi")
  expect(s.get(".m-vbg-toggle")).toBe(null)
})
